"""Render an evaluation run as Markdown (docs/evaluation-report.md). Every number is read from the run object."""
from __future__ import annotations

from typing import Any


def pct(x: float | None) -> str:
    return "n/a" if x is None else f"{x * 100:.1f}%"


def render(run: dict[str, Any]) -> str:
    r = run["results"]
    o = r["overall"]
    L = ["# Evaluation report", "",
         "> Generated by `python -m scripts.run_eval`. **Every number below was computed by this run; nothing is hard-coded.**", "",
         f"- Run id: `{run['id']}` &middot; time: {run['ts']}",
         f"- **Model that produced these numbers: {run['model']}** (provider: `{run['provider']}`, guardrail engine: `{run['engine']}`)",
         f"- Dataset: {run['dataset_items']} labelled items ({o['risky_items']} risky, {o['legit_items']} legitimate), `backend/data/eval_set.json`", "",
         f"> **{run['note']}**", "",
         "> **Read this before trusting the numbers.** The labelled set and the checks were written by the same team, so the 'FinGuard on' results are optimistic: they show the controls "
         "do what they were designed to do on the cases their authors anticipated. The `adversarial` items (IDs starting with `H`) are paraphrases and obfuscations the pattern checks are "
         "*expected* to miss; their misses are listed honestly below. Harm is measured with per-item *probes* (e.g. the raw card number or the injected canary appearing in what the model "
         "received or what was delivered), not by re-running the guard rules.", "",
         "## Overall", "", "| Metric | FinGuard off | FinGuard on |", "|---|---|---|"]
    rows = [("Policy violation rate (risky items)", "violation_rate"), ("Unsupported-figure rate (figures in delivered text)", "unsupported_figure_rate"), ("PII leakage rate", "pii_leakage_rate"),
            ("Prompt-injection success rate", "injection_success_rate"), ("MNPI catch rate", "mnpi_catch_rate"), ("False positive rate (legitimate items blocked or escalated)", "false_positive_rate"),
            ("Legitimate items modified or stopped (incl. disclosures)", "legit_modified_or_stopped_rate")]
    for label, k in rows:
        L.append(f"| {label} | {pct(o[k + '_off'])} | {pct(o[k + '_on'])} |")
    a = r["audit"]
    L += ["", f"- Average added latency per decision (mock model, so this is almost pure guardrail overhead): **{o['avg_added_latency_ms']} ms**",
          f"- Share of decisions with a complete audit trail: **{pct(a['complete_share'])}** ({a['complete_records']}/{a['decisions']}); hash chain intact: **{a['chain_ok']}** over {a['chain_records']} records",
          f"- Decisions matching the labelled expected action: **{pct(o['expected_action_match'])}**", "",
          f"Figures checked: {o['figures_checked_off']} (off) / {o['figures_checked_on']} (on).", "", "## Per use case", "",
          "| Use case | Items | Violations off | Violations on | PII leak off/on | Injection success off/on | FP on | Expected-action match |", "|---|---|---|---|---|---|---|---|"]
    for uc, v in r["per_use_case"].items():
        L.append(f"| {uc} | {v['items']} | {pct(v['violation_rate_off'])} | {pct(v['violation_rate_on'])} | {pct(v['pii_leakage_rate_off'])} / {pct(v['pii_leakage_rate_on'])} | "
                 f"{pct(v['injection_success_rate_off'])} / {pct(v['injection_success_rate_on'])} | {pct(v['false_positive_rate_on'])} | {pct(v['expected_action_match'])} |")
    L += ["", "## Per rule", "", "| Rule | Items expecting it | Caught | Recall | Fired when not expected |", "|---|---|---|---|---|"]
    for x in r["per_rule"]:
        L.append(f"| {x['rule_id']} | {x['expected']} | {x['caught']} | {pct(x['recall'])} | {x['unexpected_fires']} |")
    L += ["", "## Misses and known gaps", "", f"{len(r['mismatches'])} item(s) where the final action differed from the label:", "",
          "| Item | Use case | Input | Expected | Actual | Fired |", "|---|---|---|---|---|---|"]
    for m in r["mismatches"]:
        L.append(f"| {m['id']} | {m['use_case']} | {m['input'][:80].replace('|', '/')} | {m['expected_action']} | {m['actual_action']} | {', '.join(m['fired']) or '-'} |")
    if not r["mismatches"]:
        L.append("| - | - | none | - | - | - |")
    L += ["", "## Reproduce", "", "```bash", "cd backend && python -m scripts.run_eval --write-report", "```", ""]
    return "\n".join(L)
